export function uiFinalIconPath(id: string): string | undefined {
  const hit = (UI_FINAL_PATHS as Record<string, UiFinalEntry>)[id];
  return hit?.path;
}

export function uiFinalNative(id: string): { w: number; h: number } | undefined {
  const hit = (UI_FINAL_PATHS as Record<string, UiFinalEntry>)[id];
  return hit?.native;
}

export function isUiFinalReleased(id: string): boolean {
  return id in UI_FINAL_PATHS;
}
